CREATE TABLE campaigns (slug VARCHAR(40) PRIMARY KEY, name VARCHAR(80) NOT NULL, prerequisite VARCHAR(40) NULL, FOREIGN KEY (prerequisite) REFERENCES campaigns(slug));
INSERT INTO campaigns VALUES ('java','The Java Realm',NULL),('dsa','The Algorithm Archipelago','java');
CREATE TABLE campaign_regions (slug VARCHAR(60) PRIMARY KEY, campaign_slug VARCHAR(40) NOT NULL, name VARCHAR(80) NOT NULL, legacy_world_id BIGINT NULL, sort_order INT NOT NULL, FOREIGN KEY (campaign_slug) REFERENCES campaigns(slug), FOREIGN KEY (legacy_world_id) REFERENCES worlds(id), UNIQUE(campaign_slug,sort_order));
INSERT INTO campaign_regions SELECT slug,'java',name,id,sort_order FROM worlds;
INSERT INTO campaign_regions VALUES ('array-isles','dsa','Array Isles',NULL,1);
CREATE TABLE topics (slug VARCHAR(60) PRIMARY KEY, region_slug VARCHAR(60) NOT NULL, name VARCHAR(80) NOT NULL, active_pack VARCHAR(100) NULL, FOREIGN KEY (region_slug) REFERENCES campaign_regions(slug));
INSERT INTO topics VALUES ('arrays','array-isles','Arrays',NULL);
CREATE TABLE question_packs (id VARCHAR(100) PRIMARY KEY, topic_slug VARCHAR(60) NOT NULL, version INT NOT NULL, checksum VARCHAR(64) NOT NULL, status VARCHAR(20) NOT NULL, FOREIGN KEY (topic_slug) REFERENCES topics(slug), UNIQUE(topic_slug,version));
ALTER TABLE topics ADD FOREIGN KEY (active_pack) REFERENCES question_packs(id);
CREATE TABLE question_trails (pack_id VARCHAR(100) NOT NULL, trail_number INT NOT NULL, name VARCHAR(80) NOT NULL, PRIMARY KEY(pack_id,trail_number), FOREIGN KEY(pack_id) REFERENCES question_packs(id));
CREATE TABLE questions (id VARCHAR(100) PRIMARY KEY, topic_slug VARCHAR(60) NOT NULL, slug VARCHAR(100) NOT NULL, FOREIGN KEY(topic_slug) REFERENCES topics(slug), UNIQUE(topic_slug,slug));
CREATE TABLE question_versions (pack_id VARCHAR(100) NOT NULL, question_id VARCHAR(100) NOT NULL, trail_number INT NOT NULL, sort_order INT NOT NULL, difficulty VARCHAR(10) NOT NULL, xp_reward INT NOT NULL, public_content TEXT NOT NULL, PRIMARY KEY(pack_id,question_id), FOREIGN KEY(pack_id,trail_number) REFERENCES question_trails(pack_id,trail_number), FOREIGN KEY(question_id) REFERENCES questions(id), UNIQUE(pack_id,sort_order), CHECK(xp_reward > 0));
CREATE TABLE question_validations (pack_id VARCHAR(100) NOT NULL, question_id VARCHAR(100) NOT NULL, validator VARCHAR(30) NOT NULL, expected_answer TEXT NOT NULL, explanation TEXT NOT NULL, PRIMARY KEY(pack_id,question_id), FOREIGN KEY(pack_id,question_id) REFERENCES question_versions(pack_id,question_id));
CREATE TABLE user_campaign_progress (user_id BIGINT NOT NULL, campaign_slug VARCHAR(40) NOT NULL, unlocked_at TIMESTAMP(6) NOT NULL, completed_at TIMESTAMP(6) NULL, PRIMARY KEY(user_id,campaign_slug), FOREIGN KEY(user_id) REFERENCES players(id), FOREIGN KEY(campaign_slug) REFERENCES campaigns(slug));
CREATE TABLE user_topic_progress (user_id BIGINT NOT NULL, topic_slug VARCHAR(60) NOT NULL, pack_id VARCHAR(100) NOT NULL, unlocked_trail INT NOT NULL DEFAULT 1, completed_at TIMESTAMP(6) NULL, PRIMARY KEY(user_id,topic_slug), FOREIGN KEY(user_id) REFERENCES players(id), FOREIGN KEY(topic_slug) REFERENCES topics(slug), FOREIGN KEY(pack_id) REFERENCES question_packs(id));
CREATE TABLE user_question_progress (user_id BIGINT NOT NULL, question_id VARCHAR(100) NOT NULL, attempt_count INT NOT NULL DEFAULT 0, completed_at TIMESTAMP(6) NULL, awarded_xp INT NOT NULL DEFAULT 0, PRIMARY KEY(user_id,question_id), FOREIGN KEY(user_id) REFERENCES players(id), FOREIGN KEY(question_id) REFERENCES questions(id));
CREATE TABLE topic_badges (id VARCHAR(60) PRIMARY KEY, topic_slug VARCHAR(60) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, FOREIGN KEY(topic_slug) REFERENCES topics(slug));
INSERT INTO topic_badges VALUES ('arrays-pathfinder','arrays','Array Isles Pathfinder');
CREATE TABLE user_topic_badges (user_id BIGINT NOT NULL, badge_id VARCHAR(60) NOT NULL, earned_at TIMESTAMP(6) NOT NULL, PRIMARY KEY(user_id,badge_id), FOREIGN KEY(user_id) REFERENCES players(id), FOREIGN KEY(badge_id) REFERENCES topic_badges(id));
